```json
{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "pattern": "^[a-f0-9]{32}$",
      "description": "ID intern opac, 32 caractere hexazecimale mici; nu este GTIN."
    },
    "state": {
      "const": "published",
      "description": "Starea resursei. Publicarea lotului și eliberarea sa sunt operații independente."
    }
  },
  "required": [
    "id",
    "state"
  ],
  "additionalProperties": false,
  "description": "Structura ResolverPublished. Exemplele sunt sintetice; permisiunile și stările reale se verifică la cerere."
}
```

